void CAppearanceDef::Transfer(CPersistContext& context)
{
    context.Transfer(&Graphic);
    context.Transfer(&Animation);
    context.Transfer(&OutlineEffectAlphaRef);
    context.Transfer(&OutlineEffectAlphaBias);
